// Parse RSS items
const itemBlocks = rawXml.match(/<item>([\s\S]*?)<\/item>/g) || [];
const articles = itemBlocks.map(item => {
  let title = '';
  const cdataTitle = item.match(/<title><!\[CDATA\[([^\]]+)\]\]><\/title>/);
  const plainTitle = item.match(/<title>([^<]+)<\/title>/);
  title = (cdataTitle ? cdataTitle[1] : (plainTitle ? plainTitle[1] : '')).trim();
  let desc = '';
  const cdataDesc = item.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/);
  const plainDesc = item.match(/<description>([\s\S]*?)<\/description>/);
  desc = (cdataDesc ? cdataDesc[1] : (plainDesc ? plainDesc[1] : '')).replace(/<[^>]*>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim().substring(0,600);
  let content = '';
  const encoded = item.match(/<content:encoded><!\[CDATA\[([\s\S]*?)\]\]><\/content:encoded>/);
  if (encoded) content = encoded[1].replace(/<[^>]*>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim().substring(0,2000);
  const linkMatch = item.match(/<link>([^<]+)<\/link>/);
  const link = linkMatch ? linkMatch[1].trim() : '';
  return { title, description: desc, content: content || desc, link };
}).filter(a => a.title.length > 10);

// Deduplication: 60-day window
const today = new Date().toISOString().slice(0,10);
let usedMap = {};
try { usedMap = JSON.parse($getWorkflowStaticData('global')[STATIC_USED_KEY] || '{}'); } catch(e) {}
const cutoff = new Date(); cutoff.setDate(cutoff.getDate()-60);
Object.keys(usedMap).forEach(d => { if (d < cutoff.toISOString().slice(0,10)) delete usedMap[d]; });
const allUsed = Object.values(usedMap).flat();

// Pick fresh article from RSS
const fresh = articles.filter(a => !allUsed.includes(a.title));
let selected, source;
if (fresh.length > 0) {
  selected = fresh[Math.floor(Math.random() * fresh.length)];
  source = 'rss_feed';
} else if (articles.length > 0) {
  selected = articles[Math.floor(Math.random() * articles.length)];
  source = 'rss_reused';
} else {
  // Use CATEGORY-SPECIFIC fallback pool
  const pool = CATEGORY_FALLBACK_POOL[currentCategoryId] || CATEGORY_FALLBACK_POOL[27];
  const freshPool = pool.filter(f => !allUsed.includes(f.title));
  selected = freshPool.length > 0 ? freshPool[Math.floor(Math.random() * freshPool.length)] : pool[Math.floor(Math.random() * pool.length)];
  source = 'fallback';
}

// Save used topic
if (!usedMap[today]) usedMap[today] = [];
if (!usedMap[today].includes(selected.title)) usedMap[today].push(selected.title);
$getWorkflowStaticData('global')[STATIC_USED_KEY] = JSON.stringify(usedMap);

// Article counter for CTA
let articleCount = 0;
try { articleCount = parseInt($getWorkflowStaticData('global')[STATIC_COUNT_KEY] || '0'); } catch(e) {}
articleCount++;
$getWorkflowStaticData('global')[STATIC_COUNT_KEY] = String(articleCount);

return [{ json: {
  trendingTopic: selected.title,
  context: selected.description || '',
  sourceContent: selected.content || selected.description || '',
  sourceUrl: selected.link || '',
  topicSource: source,
  feedUrl: $json.feedUrl || '',
  articleCount,
  includeCTA: (articleCount % 20 === 0),
  _currentCategoryId: currentCategoryId,
  _rotationIndex: $json._rotationIndex
