// ============================================
// CATEGORY LIST — just outputs all categories
// The ROTATION logic is in 'Fetch Cooking RSS Feeds'
// ============================================
const CATEGORIES = [
  { id: 27, name: 'Quick & Easy Recipes' },
  { id: 28, name: 'Breakfast Recipes' },
  { id: 29, name: 'Lunch Ideas' },
  { id: 30, name: 'Dinner Recipes' },
  { id: 31, name: 'Healthy Recipes' },
  { id: 32, name: 'Vegetarian Recipes' },
  { id: 33, name: 'Desserts & Sweets' },
  { id: 34, name: 'Snacks & Appetizers' },
  { id: 35, name: 'Beverages & Drinks' },
  { id: 36, name: 'Cooking Tips & Guides' }
];
return CATEGORIES.map(c => ({ json: c }));

// ============================================
