function pickBestImage(nodeName) {
  try {
    const apiResponse = $(nodeName).first().json;
    const photos = (apiResponse && apiResponse.photos) ? apiResponse.photos : [];
    if (photos.length === 0) return null;
    const available = photos.filter(p => !usedImgIds.has(p.id));
    if (available.length === 0) return null;
    const pick = available[Math.floor(Math.random() * Math.min(4, available.length))];
    if (!pick || !pick.src) return null;
    usedImgIds.add(pick.id);
    return {
      url:   pick.src.large2x || pick.src.large || pick.src.medium || '',
      alt:   pick.alt || '',
      pName: pick.photographer || 'Pexels',
      pUrl:  pick.photographer_url || 'https://www.pexels.com',
      pgUrl: pick.url || 'https://www.pexels.com',
      source: 'pexels'
    };
  } catch(e) { return null; }
}

